        if (amount < c.minTxnAmount()) {
            assertTrue(finalReward == initialReward, "Reward should not be given for small transfers");
        } else {
            // For amounts >= minTxnAmount, reward may or may not be given depending on contract balance
            // We don't assert exact equality because SMT doesn't allow that
            // Instead we check that reward is added if contract has enough balance
            // This would require a different approach, so we skip that case
        }
    }
}

