import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address sender, address recipient, uint256 amount) public {
        vm.assume(sender != address(0) && recipient != address(0) && sender != recipient);
        vm.assume(amount > 0 && amount <= 1e30);
        // Record txReward before transfer
        uint256 rewardBefore = c.txReward(recipient);
        // Perform a transfer from sender to recipient
        // Need to give sender some tokens first
        // Use the onlyOwner to mint? No, we can't directly call _mint. Instead, use the constructor owner (this) to transfer.
        // But we need sender to have tokens. Let's use vm.prank to act as owner and transfer to sender.
        vm.prank(c._owner());
        c.transfer(sender, 1e20); // Give sender some tokens
        vm.prank(sender);
        c.transfer(recipient, amount);
        // Now call allowance
        c.allowance(sender, recipient);
        // Assert that txReward of recipient did not decrease
        assertTrue(c.txReward(recipient) >= rewardBefore);
    }
}

