import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller1 != address(c));
        vm.assume(caller2 != address(0) && caller2 != address(c));
        vm.assume(caller1 != caller2);
        amount1 = bound(amount1, 1, 1e22);
        amount2 = bound(amount2, 1, 1e22);

        // Set up initial balances
        vm.deal(caller1, 1 ether);
        vm.deal(caller2, 1 ether);
        vm.prank(caller1);
        (bool success1, ) = address(c).call{value: 1 ether}("");
        vm.assume(success1);
        vm.prank(caller2);
        (bool success2, ) = address(c).call{value: 1 ether}("");
        vm.assume(success2);

        // Do a transfer from caller1 to caller2 that may trigger reward
        vm.prank(caller1);
        c.transfer(caller2, amount1);

        vm.prank(caller2);
        c.transfer(caller1, amount2);

        // Record txReward for both after transfers but before allowance call
        uint256 reward1Before = c.txReward(caller1);
        uint256 reward2Before = c.txReward(caller2);

        // Call allowance (the trigger that should not change rewards in reference)
        c.allowance(caller1, caller2);

        uint256 reward1After = c.txReward(caller1);
        uint256 reward2After = c.txReward(caller2);

        // General rule: allowance does not modify txReward for any account
        assertTrue(reward1Before == reward1After && reward2Before == reward2After, "allowance changed txReward");
    }
}

